const _tctOpMap = {
    ">": (a, b) => a > b,
    ">=": (a, b) => a >= b,
    "==": (a, b) => a == b,
    "<=": (a, b) => a <= b,
    "<": (a, b) => a < b,
    "!=": (a, b) => a != b
};

const _tctGetEndingImageEl = () => {
    const imageContainer = document.querySelector(".person_image");
    if (!imageContainer) return null;
    if (imageContainer.tagName && imageContainer.tagName.toLowerCase() === "img") {
        return imageContainer;
    }
    return imageContainer.querySelector("img");
};

const _tctReadVariable = (name) => {
    if (!name || typeof name !== "string") return undefined;
    if (!/^[A-Za-z_$][A-Za-z0-9_$]*$/.test(name)) return undefined;
    try {
        return eval("(typeof " + name + " !== 'undefined') ? " + name + " : undefined;");
    } catch (_err) {
        return undefined;
    }
};

const _tctParseConditionValue = (value) => {
    if (value == null || value === "") return "";
    const n = Number(value);
    if (!Number.isNaN(n)) return n;
    return value;
};

const _tctCheckOutcomeCondition = (entry, finalOutcome) => {
    const cond = String(entry?.outcomeCondition || "ignore");
    if (cond === "ignore") return true;
    return cond === String(finalOutcome || "");
};

const _tctMatchesPrimaryCondition = (entry, quickstats, finalOutcome) => {
    if (!_tctCheckOutcomeCondition(entry, finalOutcome)) return false;

    const cond = String(entry?.outcomeCondition || "ignore");
    if (cond !== "ignore") {
        return true;
    }

    const opFn = _tctOpMap[entry?.operator] || _tctOpMap[">"];
    const left = quickstats?.[Number(entry?.variable) || 0];
    const right = Number(entry?.amount) || 0;
    return opFn(left, right);
};

const _tctCheckExtraConditions = (entry, playerAnswers) => {
    if (Array.isArray(entry.variableConditions) && entry.variableConditions.length > 0) {
        const operator = entry.variableConditionOperator || "AND";
        const results = entry.variableConditions.map((cond) => {
            const left = _tctReadVariable(cond.variable);
            const right = _tctParseConditionValue(cond.value);
            const opFn = _tctOpMap[cond.comparator] || _tctOpMap["=="];
            return opFn(left, right);
        });

        if (operator === "AND") {
            if (!results.every((r) => r)) return false;
        } else if (operator === "OR") {
            if (!results.some((r) => r)) return false;
        }
    }

    const answerType = entry.answerConditionType || "ignore";
    if (answerType !== "ignore") {
        const rawAnswers = String(entry.answerConditionAnswers || entry.answerConditionAnswer || "").trim();
        const answerIds = rawAnswers
            .split(/[s,]+/)
            .filter((v) => v.length > 0)
            .map((v) => Number(v))
            .filter((v) => Number.isFinite(v));

        if (answerIds.length === 0) return false;

        const hasAny = Array.isArray(playerAnswers) && answerIds.some((id) => playerAnswers.includes(id));
        if (answerType === "has" && !hasAny) return false;
        if (answerType === "not_has" && hasAny) return false;
    }

    return true;
};

const playEndingSong = (title, artist, cover, url) => {
    if (!url) return;
    const PlaylistCtor = (typeof window !== "undefined" && window.Playlist)
        || (typeof Playlist !== "undefined" ? Playlist : null);
    const SongCtor = (typeof window !== "undefined" && window.Song)
        || (typeof Song !== "undefined" ? Song : null);
    const changePlaylistFn = (typeof window !== "undefined" && window.changePlaylist)
        || (typeof changePlaylist === "function" ? changePlaylist : null);

    if (PlaylistCtor && SongCtor && typeof changePlaylistFn === "function") {
        try {
            const playlist = new PlaylistCtor();
            const song = new SongCtor(title || "", artist || "", cover || "", url);
            if (typeof playlist.addSong === "function") {
                playlist.addSong(song);
                changePlaylistFn(playlist);
                return;
            }
        } catch (err) {
            console.warn("Failed to route ending song:", err);
        }
    }

    const audioEl = document.getElementById("audio") || document.querySelector("audio#audio, audio");
    if (!audioEl) return;

    if (audioEl.src !== url) {
        audioEl.src = url;
    }

    const player = document.getElementById("player");
    if (player) {
        const titleEl = player.querySelector("#title");
        const artistEl = player.querySelector("#artist");
        const coverEl = player.querySelector("#cover");
        if (titleEl) titleEl.textContent = title || "";
        if (artistEl) artistEl.textContent = artist || "";
        if (coverEl && cover) coverEl.src = cover;
    }

    const playPromise = audioEl.play?.();
    if (playPromise && typeof playPromise.catch === "function") {
        playPromise.catch(() => {});
    }
};

const styleEndingDescription = () => {
    const desc = document.querySelector("#final_results_description");
    if (!desc) return;

    const e = campaignTrail_temp;
    const theme = e._endingTheme || {};
    const bg = theme.backgroundColor || "#ffffff";
    const fg = theme.textColor || "#000000";
    const border = theme.accentColor || "#11299e";

    Object.assign(desc.style, {
        textAlign: "left",
        width: "72%",
        maxHeight: "20em",
        minHeight: "8em",
        height: "auto",
        display: "block",
        margin: "0 auto",
        overflowY: "auto",
        overflowX: "hidden",
        whiteSpace: "normal",
        overflowWrap: "anywhere",
        wordBreak: "break-word",
        transform: "translateZ(0)",
        backgroundColor: bg,
        color: fg,
        border: "2px solid " + border,
        borderRadius: "4px",
        padding: "10px"
    });

    desc.dataset.endingStyled = "1";
};

const applyEndingImage = (slide) => {
    const imageEl = _tctGetEndingImageEl();
    if (!imageEl || !slide) return;

    if (slide.image === false) {
        imageEl.style.display = "none";
        imageEl.removeAttribute("src");
        return;
    }

    if (!imageEl.dataset.endingStyled) {
        const e = campaignTrail_temp;
        const theme = e._endingTheme || {};
        const border = theme.accentColor || "#11299e";
        Object.assign(imageEl.style, {
            border: "3px solid " + border,
            display: "block",
            width: "210px",
            height: "250px",
            objectFit: "cover"
        });
        imageEl.dataset.endingStyled = "1";
    } else {
        imageEl.style.display = "block";
        const e = campaignTrail_temp;
        const theme = e._endingTheme || {};
        imageEl.style.border = "3px solid " + (theme.accentColor || "#11299e");
    }

    if (slide.image && imageEl.getAttribute("src") !== slide.image) {
        imageEl.src = slide.image;
    }
};

const applyEndingButtons = () => {
    const e = campaignTrail_temp;
    const theme = e._endingTheme || {};
    const imageEl = _tctGetEndingImageEl();
    const desc = document.querySelector("#final_results_description");
    if (!imageEl || !imageEl.parentNode) return;

    let btnContainer = document.getElementById("ending_slide_buttons");
    if (!btnContainer) {
        btnContainer = document.createElement("div");
        btnContainer.id = "ending_slide_buttons";
    }

    if (e.page === 0 && desc) {
        if (btnContainer.parentNode !== desc) {
            desc.appendChild(btnContainer);
        }
        Object.assign(btnContainer.style, {
            display: "flex",
            justifyContent: "flex-end",
            gap: "20px",
            position: "static",
            width: "100%",
            boxSizing: "border-box",
            marginTop: "14px",
            paddingTop: "10px",
            borderTop: "1px solid " + (theme.accentColor || "#11299e")
        });
    } else {
        if (btnContainer.parentNode !== imageEl.parentNode) {
            imageEl.parentNode.insertBefore(btnContainer, imageEl.nextSibling);
        }
        Object.assign(btnContainer.style, {
            display: "flex",
            justifyContent: "flex-start",
            gap: "20px",
            left: "13px",
            top: "280px",
            position: "absolute",
            width: "auto",
            marginTop: "0",
            paddingTop: "0",
            borderTop: "none"
        });
    }

    let buttonsHtml = "";
    if (e.page > 0) {
        buttonsHtml += '<button onclick="endingConstructor(-1)">Back</button>';
    }
    if (e.page < e.endingSlides.length - 1) {
        buttonsHtml += '<button onclick="endingConstructor(1)">Next</button>';
    }

    if (btnContainer.innerHTML !== buttonsHtml) {
        btnContainer.innerHTML = buttonsHtml;
    }

    const buttonBg = theme.accentColor || "#11299e";
    btnContainer.querySelectorAll("button").forEach((btn) => {
        Object.assign(btn.style, {
            backgroundColor: buttonBg,
            border: "1px solid " + buttonBg,
            color: "#ffffff",
            padding: "6px 14px",
            cursor: "pointer",
            fontWeight: "bold"
        });
    });
};

const syncEndingSlideDom = () => {
    const e = campaignTrail_temp;
    const slide = e.endingSlides?.[e.page];
    if (!slide) return;

    styleEndingDescription();
    applyEndingImage(slide);
    applyEndingButtons();

    if (slide.audio && slide.audio.url) {
        const key = [slide.audio.title || "", slide.audio.artist || "", slide.audio.url || ""].join("|");
        const globalKey = (typeof window !== "undefined" && window.__tctLastEndingAudioKey) || "";

        const currentAudioEl = document.getElementById("audio") || document.querySelector("audio#audio, audio");
        const currentSrc = currentAudioEl ? (currentAudioEl.currentSrc || currentAudioEl.src || "") : "";
        const sameSrcLoaded = !!currentSrc && currentSrc.includes(slide.audio.url);

        if (e._endingAudioPlayedKey !== key && globalKey !== key && !sameSrcLoaded) {
            playEndingSong(slide.audio.title, slide.audio.artist, slide.audio.cover, slide.audio.url);
        }

        e._endingAudioPlayedKey = key;
        if (typeof window !== "undefined") {
            window.__tctLastEndingAudioKey = key;
        }
    }
};

const syncEndingSlideDomDeferred = () => {
    requestAnimationFrame(() => {
        syncEndingSlideDom();
    });
};

campaignTrail_temp.hailMaryMoviePosterUrl = "data:image/png;base64,";

const _tctMovieReviewSlide = () => ({
    title: "Breitbart.com | Entertainment",
    subtitle: "Hollywood's Hail Mary Pass to Whitewash History Fell FLAT",
    content: "<div style='font-family:Arial,Helvetica,sans-serif;'><div style='border-top:5px solid #111;border-bottom:1px solid #aaa;padding:6px 0;margin-bottom:12px;font-size:12px;text-transform:uppercase;letter-spacing:1px;'><b>Culture</b> &nbsp; | &nbsp; October 27, 2013</div><p style='font-size:13px;color:#555;'><b>By Ben Shapiro</b></p><p>There is perhaps no historical figure modern Hollywood loves more than Ted Kennedy. Not John F. Kennedy. Not Robert Kennedy. Ted Kennedy—the man whose political career somehow survived every bad decision, every personal scandal, and now, apparently, every historical reality. HBO's latest prestige production, <i>Hail Mary</i>, asks viewers to believe that the most unlikely presidency in modern American history was not merely successful, but morally indispensable. Unsurprisingly, the film spends nearly three hours congratulating itself for that premise.</p><p>Brendan Gleeson is buried under makeup and directed to spend most of the movie looking exhausted, coughing into handkerchiefs, and delivering speeches about sacrifice. Ian McDiarmid's Joe Lieberman mostly lurks nearby to reassure the audience that whatever the administration is doing is secretly brilliant. Both actors are capable of far more, but the screenplay gives them little besides liberal mythology dressed up as tragedy.</p><p>Patricia Arquette is good enough in the lead role as Mary Landrieu. She gives the Vice President a believable mixture of loyalty, ambition, and unease, especially as she realizes that she is inheriting a collapsing administration while everyone around her pretends otherwise. It is the closest the movie comes to acknowledging that political power might involve something more complicated than noble Democrats fighting cartoon villains.</p><p>The surprise standout is Topher Grace as Patrick Kennedy. He does not receive nearly enough screen time, but his story arc is easily the film's most interesting. Patrick's journey toward sobriety is handled with unusual restraint, and the quiet foreshadowing of his eventual successful Senate campaign suggests a richer movie hiding somewhere beneath this one. HBO somehow stumbled into a better story than the one it actually chose to tell.</p><p>The general election barely appears at all. Jon Hamm makes a small appearance as Bill Frist, Michael Shannon shows up briefly as Mike Huckabee, and Greg Kinnear's short scene as Steve Forbes is genuinely enjoyable. Each leaves the audience wishing the campaign itself had received more attention than another lovingly photographed Kennedy family crisis.</p><p>Ultimately, <i>Hail Mary</i> is not interested in examining history. It wants absolution. Every policy failure becomes noble, every political calculation becomes courageous, and every critic is either cynical or stupid. There is a fascinating story buried here, but HBO was too busy whitewashing the Kennedy legacy to tell it.</p><p><b>Rating: 2½ out of 5 stars.</b></p><div style='margin-top:16px;padding-top:8px;border-top:1px solid #aaa;font-size:11px;color:#666;'><i>Hail Mary</i> — HBO Films, 2013. Runtime: 176 minutes.</div></div>",
    image: campaignTrail_temp.hailMaryMoviePosterUrl
});

const _tctWarKennedySlide = () => ({
    title: "The Boston Globe | Opinion",
    subtitle: "The Last Kennedy Leaves Behind More Questions Than Answers",
    content: "<div style='font-family:Georgia,Times New Roman,serif;'><div style='border-top:4px solid #222;border-bottom:1px solid #999;padding:6px 0;margin-bottom:12px;font-family:Arial,Helvetica,sans-serif;font-size:12px;'><b>EDITORIAL BOARD</b> &nbsp; | &nbsp; January 17, 2007</div><p>Edward Moore Kennedy died yesterday at the age of seventy-four, bringing to a close one of the most improbable political careers in American history. Few Americans who watched the aftermath of Chappaquiddick in 1969 believed they would one day call him Mr. President. Fewer still imagined he would defeat George W. Bush in 2000, against nearly every expectation, and lead the nation through the trauma that followed the attacks of September 11.</p><p>His presidency will remain fiercely debated. Supporters will remember Americare and a lifetime spent insisting that government had an obligation to protect the vulnerable. Critics will remember his personal failings, missed opportunities, and an administration that often seemed to buckle beneath the weight of its own ambitions. Like the man himself, the Kennedy presidency resists easy judgment.</p><p>Patrick Kennedy has said that, shortly before his father's death, the former President privately expressed regret that he had chosen Mary Landrieu not as his successor, but as his Vice President. Whether those words were ever spoken is impossible to know. Yet they have taken on new significance as President Landrieu escalates the war in Iraq with a ferocity many Democrats believe Kennedy himself would never have accepted.</p><p>There will never be a satisfying answer. Ted Kennedy spent much of his public life attempting to outrun the worst day of it. Sometimes he succeeded. Sometimes he did not. But his impossible victory in 2000 ensured that the final chapter of the Kennedy story would remain, fittingly, unfinished.</p><div style='margin-top:16px;padding-top:8px;border-top:1px solid #999;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#666;'>From The Boston Globe Opinion Section — January 17, 2007</div></div>",
    image: "https://i.imgur.com/Pyln2Le.jpeg"
});

const _tctIsVictory = (finalOutcome) => String(finalOutcome || "").toLowerCase() === "win";

const _tctBuildSlides = (entry, quickstats, finalOutcome) => {
    if (entry && entry.endingSlidesJson) {
        try {
            const parsed = JSON.parse(entry.endingSlidesJson);
            if (Array.isArray(parsed) && parsed.length > 0) {
                const normalizeSlide = (slide) => ({
                    variable: Number(slide?.variable ?? 0),
                    operator: slide?.operator || ">",
                    amount: Number(slide?.amount ?? 0),
                    outcomeCondition: slide?.outcomeCondition || "ignore",
                    title: slide?.title || "",
                    subtitle: slide?.subtitle || "",
                    content: slide?.content || "",
                    image: slide?.image,
                    audio: slide?.audio && slide.audio.url ? {
                        title: slide.audio.title || "",
                        artist: slide.audio.artist || "",
                        cover: slide.audio.cover || "",
                        url: slide.audio.url || ""
                    } : undefined
                });

                const hasGroups = parsed.some((slide) => slide && slide.slideGroup);
                if (!hasGroups) {
                    const slides = parsed.map((slide) => normalizeSlide(slide));
                    if (_tctIsVictory(finalOutcome)) {
                        if (endingIraqPath === "deal") slides.push(_tctMovieReviewSlide());
                        else if (endingIraqPath === "war") slides.push(_tctWarKennedySlide());
                    }
                    return slides;
                }

                const groupMap = new Map();
                const groupOrder = [];
                for (const slide of parsed) {
                    const groupKey = slide?.slideGroup || "main";
                    if (!groupMap.has(groupKey)) {
                        groupMap.set(groupKey, []);
                        groupOrder.push(groupKey);
                    }
                    groupMap.get(groupKey).push(slide);
                }

                const playerAnswers = campaignTrail_temp?.player_answers || [];
                const selectedSlides = [];

                for (const groupKey of groupOrder) {
                    const groupSlides = groupMap.get(groupKey) || [];
                    let selected = groupSlides.find((slide) => {
                        return _tctMatchesPrimaryCondition(slide, quickstats, finalOutcome)
                            && _tctCheckExtraConditions(slide, playerAnswers);
                    });
                    if (!selected) selected = groupSlides[0];
                    if (selected) selectedSlides.push(normalizeSlide(selected));
                }

                if (_tctIsVictory(finalOutcome)) {
                    if (endingIraqPath === "deal") selectedSlides.push(_tctMovieReviewSlide());
                    else if (endingIraqPath === "war") selectedSlides.push(_tctWarKennedySlide());
                }
                return selectedSlides;
            }
        } catch (err) {
            console.warn("Invalid endingSlidesJson for ending", entry?.id, err);
        }
    }

    const fallbackSlide = {
        title: entry?.endingTitle || "",
        subtitle: entry?.endingSubtitle || "",
        content: entry?.endingText || "",
        image: entry?.endingHideImage ? false : (entry?.endingImage || undefined)
    };

    if (entry?.audioUrl) {
        fallbackSlide.audio = {
            title: entry.audioTitle || "",
            artist: entry.audioArtist || "",
            cover: entry.audioCover || "",
            url: entry.audioUrl || ""
        };
    }

    const slides = [fallbackSlide];
    if (_tctIsVictory(finalOutcome)) {
                        if (endingIraqPath === "deal") slides.push(_tctMovieReviewSlide());
                        else if (endingIraqPath === "war") slides.push(_tctWarKennedySlide());
                    }
    return slides;
};

const _tctConstructSlide = (direction = 1) => {
    const e = campaignTrail_temp;
    if (!Array.isArray(e.endingSlides) || e.endingSlides.length === 0) return "";

    e.page += direction;
    if (e.page < 0) e.page = 0;
    if (e.page >= e.endingSlides.length) e.page = e.endingSlides.length - 1;

    const currentSlide = e.endingSlides[e.page];
    if (!currentSlide) return "";

    let html = "";
    if (currentSlide.title) html += "<h3>" + currentSlide.title + "</h3>";
    if (currentSlide.subtitle) html += "<h4>" + currentSlide.subtitle + "</h4>";
    html += (currentSlide.content || "") + "<br><br>";
    return html;
};

endingConstructor = (direction = 1) => {
    const desc = document.querySelector("#final_results_description");
    if (!desc) return;
    desc.innerHTML = _tctConstructSlide(direction);
    syncEndingSlideDomDeferred();
};

endingPicker = (out, totv, aa, quickstats) => {
    const playerAnswers = campaignTrail_temp?.player_answers || [];
    for (const entry of _tctEndingDefs) {
        let isMatch = false;

        try {
            const parsed = entry.endingSlidesJson ? JSON.parse(entry.endingSlidesJson) : [];
            if (Array.isArray(parsed) && parsed.length > 0) {
                const groupMap = new Map();
                for (const slide of parsed) {
                    const groupKey = slide?.slideGroup || "main";
                    if (!groupMap.has(groupKey)) {
                        groupMap.set(groupKey, []);
                    }
                    groupMap.get(groupKey).push(slide);
                }

                const mainSlides = groupMap.get("main") || parsed;
                let validMain = mainSlides.find((slide) => {
                    return _tctMatchesPrimaryCondition(slide, quickstats, out)
                        && _tctCheckExtraConditions(slide, playerAnswers);
                });

                if (validMain) isMatch = true;
            } else {
                if (_tctMatchesPrimaryCondition(entry, quickstats, out) && _tctCheckExtraConditions(entry, playerAnswers)) {
                    isMatch = true;
                }
            }
        } catch(e) {
            if (_tctMatchesPrimaryCondition(entry, quickstats, out) && _tctCheckExtraConditions(entry, playerAnswers)) {
                isMatch = true;
            }
        }

        if (isMatch) {
            const e = campaignTrail_temp;
            e.multiple_endings = true;
            e.page = -1;
            e._endingTheme = {
                accentColor: entry?.endingAccentColor || "#11299e",
                backgroundColor: entry?.endingBackgroundColor || "#ffffff",
                textColor: entry?.endingTextColor || "#000000"
            };
            e.endingSlides = _tctBuildSlides(entry, quickstats, out);
            e._endingAudioPlayedKey = (typeof window !== "undefined" && window.__tctLastEndingAudioKey) || "";

            const html = _tctConstructSlide(1);
            syncEndingSlideDomDeferred();
            return html;
        }
    }

    return "";
};


